spec = {
    "wave": "kama-r53-w1",
    "reportDir": ".ufo/waves/round-53/w1/out",
    "maxLanes": len(items),
    "axes": ["calibration", "operability"],
    "context": CONTEXT,
    "items": items,
}
names = [i["name"] for i in items]
assert len(names) == len(set(names)), names
os.makedirs(os.path.join(W, "w1"), exist_ok=True)
json.dump(spec, open(os.path.join(W, "w1", "spec.json"), "w"), indent=1)
c = Counter(i["role"] for i in items)
attack = sum(c[r] for r in ("reviewer", "critic", "mutation-tester"))
print(len(items), dict(c), "attack", attack, f"{attack / len(items):.0%}")
